HTTP_OUTCOMES = {
    400: ("Invalid provider request", "The provider rejected the request format or data. Check the item metadata and provider response before retrying."),
    401: ("Authentication required", "The provider requires valid authentication. Reconnect the selected account before retrying."),
    403: ("Access denied", "The provider denied access. Check the selected account's permissions and credentials before retrying."),
    404: ("Requested resource not found", "The provider could not find the requested resource or endpoint. Check the destination connection and item identity."),
    409: ("Destination conflict", "The provider reported a conflict with its current state. Refresh the destination before retrying; an entry may already exist."),
    420: ("Provider limit reported", "The provider reported HTTP 420. Check its response and documented account or request limits before retrying."),
    422: ("Item data rejected", "The provider could not accept the supplied data. Check the item IDs, values and dates before retrying."),
    423: ("Account or resource locked", "The provider reported that the account or resource is locked. Check its status on the provider before retrying."),
    426: ("Provider upgrade required", "The provider requires an upgrade before accepting this operation. Check its response for the required protocol or account changes."),
    429: ("Provider request limit reached", "The provider is limiting requests. Wait for its retry interval before trying again."),
}


def outcome_text(code: str) -> tuple[str, str] | None:
    floppy = re.fullmatch(r"floppy_http_([45][0-9]{2})(?::.*)?", code, flags=re.DOTALL)
    if floppy:
        code = f"http_{floppy[1]}"
    elif code.startswith("floppy_error:"):
        code = "floppy_error"
    outcome = OUTCOMES.get(ALIASES.get(code, code))
    if outcome:
        return outcome
    http = re.fullmatch(r"http[:_]([45][0-9]{2})", code)
    if http:
        status = int(http[1])
        if status in HTTP_OUTCOMES:
            return HTTP_OUTCOMES[status]
        if status >= 500:
            return "Provider service error", "The provider reported a server error. Check its availability and current destination state before retrying."
        return "Provider request rejected", "The provider rejected the request. Check the HTTP status, account permissions and supplied data before retrying."
    exception = re.fullmatch(r"(add_failed|remove_failed|write_failed):[a-z_][a-z0-9_]*", code)
    return OUTCOMES[exception[1]] if exception else None
